const level=$("#libraryLevel")?.value||"all";
const list=libraryData.filter(x=>(!search||(x.title+" "+x.desc+" "+x.summary+" "+x.body).toLowerCase().includes(search))&&(libraryTrack==="all"||x.track===libraryTrack)&&(level==="all"||x.stage===level));
