$("#libraryGrid").innerHTML=list.length?list.map(x=>'<article class="library-card" data-library-topic="'+x.id+'" role="button" tabindex="0" aria-label="افتح موضوع '+safeText(x.title)+'"><span class="library-track-mark track-mark-'+x.track+'" aria-hidden="true"></span><div class="library-card-kicker">'+safeText(names[x.track]||"مكتبة المعرفة")+' · '+safeText(x.stage)+'</div><h3>'+safeText(x.title)+'</h3><p>'+safeText(x.desc)+'</p><span class="library-open-label">اقرأ واستكشف الموضوع ←</span></article>').join(""):'<div class="no-results">لا توجد موضوعات مطابقة لهذه التصفية. جرّب مساراً أو مرحلة أخرى.</div>';
