function renderLanguageWords(){
 const lang=$("#vocabularyLanguage").value, q=$("#vocabularySearch").value.trim().toLocaleLowerCase();
 const items=(languageVocabulary[lang]||[]).filter(item=>(item.word+" "+item.meaning+" "+item.label).toLocaleLowerCase().includes(q));
 $("#languageWordGrid").innerHTML=items.length?items.map((item,i)=>'<button class="language-word-card" type="button" data-language-word="'+safeText(item.word)+'"><span class="language-word-number">'+String(i+1).padStart(2,"0")+'</span><strong>'+safeText(item.word)+'</strong><span>'+safeText(item.meaning)+'</span><small>'+safeText(item.label)+'</small></button>').join(""):'<div class="empty-state">لا توجد كلمة مطابقة في مجموعة البداية.</div>';
}
async function translateLanguageText(){
 const query=$("#languageQuery").value.trim(), from=$("#languageFrom").value, to=$("#languageTo").value, result=$("#languageResult"), button=$("#translateLanguage");
 if(!query){result.textContent="اكتب كلمة أو جملة أولاً.";return;}
 if(from===to){result.textContent=query;return;}
 button.disabled=true;button.textContent="جارٍ الترجمة…";result.textContent="يتم طلب الترجمة…";
 try{
  const cacheKey="translation:"+from+":"+to+":"+query;
  const cached=store.get(cacheKey,null);
  let translated=cached;
  if(!translated){
   const url="https://api.mymemory.translated.net/get?q="+encodeURIComponent(query)+"&langpair="+encodeURIComponent(from+"|"+to);
   const response=await fetch(url);
   if(!response.ok)throw new Error("translation service unavailable");
   const payload=await response.json();
   translated=payload&&payload.responseData&&payload.responseData.translatedText;
   if(!translated||payload.responseStatus!==200)throw new Error("no translation");
   const decoder=document.createElement("textarea");decoder.innerHTML=translated;translated=decoder.value;
   store.set(cacheKey,translated);
  }
  result.innerHTML='<strong>'+safeText(translated)+'</strong><small>من '+safeText(languageNames[from])+' إلى '+safeText(languageNames[to])+' · راجع السياق قبل اعتماد الترجمة.</small><button type="button" class="secondary-button language-copy" id="copyLanguageTranslation">نسخ الترجمة</button>';
  $("#copyLanguageTranslation").addEventListener("click",async()=>{try{await navigator.clipboard.writeText(translated);showToast("تم نسخ الترجمة.");}catch(_){showToast("تعذر النسخ تلقائياً؛ حدد النص وانسخه.");}});
 }catch(_){result.textContent="تعذرت الترجمة الآن. تحقق من الاتصال وحاول لاحقاً؛ قد تكون الخدمة محدودة أو لا تدعم هذا الزوج من اللغات."; }
 finally{button.disabled=false;button.textContent="ترجم الآن ←";}
}

